L43: export class SketchProgram{

import { LESSONS, SKETCHES, LabModel } from './engine.js';
import { LabScene, PARTS } from './scene.js';

const $=id=>document.getElementById(id);
const model=new LabModel();
const sketches={...SKETCHES};
let current=0,scene=null,xray=false,topView=false,lastTime=0,lastUI=0,audio=null,tour=null,tourElapsed=0,manualMode=false,savedTourSketches=null;
let completed=new Set();
try{completed=new Set(JSON.parse(localStorage.getItem('pipit-completed')||'[]').filter(id=>LESSONS.some(l=>l.id===id)));}catch{}

function thumb(id){
  const board='<path d="m3 22 24-13 25 12-24 15Z" fill="#296650"/><path d="m3 22 25 14 24-15v4L28 39 3 25Z" fill="#1c4937"/><path d="m10 21 9-5 9 5-9 5Z" fill="#25302b"/><path d="m29 21 8-4 8 4-8 5Z" fill="#c6cdc8"/><path d="m22 29 4-2 4 2-4 3Zm8-4 4-2 4 2-4 3Zm9-5 4-2 4 2-4 3Z" fill="#e2e2cd"/>';
  const extra={board:'',pwm:'<circle cx="41" cy="30" r="3" fill="#e3b050"/>',dial:'<path d="M35 30q9 7 17-3" fill="none" stroke="#95896b" stroke-width="2"/><ellipse cx="53" cy="25" rx="8" ry="4" fill="#2a674d"/><path d="M49 21v-5h8v5Z" fill="#b25545"/>',distance:'<rect x="47" y="13" width="18" height="11" rx="1" fill="#3d8063"/><circle cx="51" cy="18" r="3" fill="#bcc8bf"/><circle cx="60" cy="18" r="3" fill="#bcc8bf"/>',chirp:'<ellipse cx="54" cy="24" rx="8" ry="5" fill="#1c4937"/><path d="M48 20v-6q6-5 12 0v6Z" fill="#29342e"/><ellipse cx="54" cy="14" rx="6" ry="3" fill="#35463c"/>',plant:'<path d="m51 26 3 10h9l3-10Z" fill="#9c5f48"/><path d="M58 27V12" stroke="#4d7b43" stroke-width="2"/><path d="M58 18Q45 8 47 17q4 6 11 5M58 23q12-15 12-6-1 7-12 8M58 14q-2-10 4-8 5 4-4 8" fill="#548943"/>'}[id];
  return `<svg class="lesson-thumb" viewBox="0 0 72 44" aria-hidden="true"><g transform="${id==='board'||id==='pwm'?'translate(5 0)':'translate(0 0) scale(.78)'}">${board}</g>${extra}</svg>`;
}
function renderNav(){
  $('mobile-lessons').innerHTML=LESSONS.map((l,i)=>`<option value="${i}" ${i===current?'selected':''}>${String(i+1).padStart(2,'0')} · ${l.title}</option>`).join('');
  $('lessons').innerHTML=LESSONS.map((l,i)=>`<button class="lesson-link ${i===current?'active':''}" data-lesson="${l.id}" ${i===current?'aria-current="step"':''}>${thumb(l.id)}<span><span class="lesson-name">${l.title}</span><span class="lesson-type"><span class="lesson-index">${completed.has(l.id)?'✓':String(i+1).padStart(2,'0')}</span>${l.tag}</span></span></button>`).join('');
  $('lessons').querySelectorAll('button').forEach((b,i)=>b.addEventListener('click',()=>{stopTour();selectLesson(i);history.replaceState(null,'','#'+LESSONS[i].id);}));
  $('progress-count').textContent=`${completed.size} / 6`;$('progress-fill').style.width=`${completed.size/6*100}%`;
}
function markComplete(){completed.add(LESSONS[current].id);try{localStorage.setItem('pipit-completed',JSON.stringify([...completed]));}catch{}renderNav();}
function range(key,title,min,max,step,unit){return `<div class="input-block"><div class="range-label"><label for="input-${key}">${title}</label><output id="output-${key}" for="input-${key}">${model.settings[key]} ${unit}</output></div><div class="range-row"><input type="range" id="input-${key}" data-input="${key}" min="${min}" max="${max}" step="${step}" value="${model.settings[key]}" aria-label="${title}"></div><div class="range-ticks"><span>${min} ${unit}</span><span>${max} ${unit}</span></div></div>`;}
function renderInputs(){
  const id=model.lesson;
  $('inputs').innerHTML=id==='pwm'?range('duty','Duty cycle',0,100,1,'%')+range('frequency','Pulse frequency',.25,10,.25,'Hz'):id==='dial'?range('dial','Dial position',0,100,1,'%'):id==='distance'?range('distance','Object distance',5,100,1,'cm'):id==='chirp'?range('tone','Tone frequency',80,2000,10,'Hz')+'<button id="audio" class="button audio-button">Enable sound ♫</button>':id==='plant'?range('moisture','Soil moisture',0,100,.1,'%')+'<button id="dry-soil" class="button">Dry the soil → 20%</button>':'';
  $('inputs').querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>{stopTour();setInput(input.dataset.input,Number(input.value));}));
  $('audio')?.addEventListener('click',toggleAudio);
  $('dry-soil')?.addEventListener('click',()=>{stopTour();setInput('moisture',20);});
}
function setInput(key,value,relative=false){
  if(relative)value+=model.settings[key];model.setInput(key,value);
  // Keep editable actuator settings synchronized with the controls.
  if(model.lesson==='pwm'&&(key==='duty'||key==='frequency')){
    $('code').value=$('code').value.replace(new RegExp(`(${key}\\s*:\\s*)-?\\d+(?:\\.\\d+)?`),`$1${model.settings[key]}`);
  }
  if(model.lesson==='chirp'&&key==='tone')$('code').value=$('code').value.replace(/(frequency\s*:\s*)\d+(?:\.\d+)?/,`$1${model.settings.tone}`);
  updateUI();updateAudio();
}
function lines(){const n=Math.max(6,$('code').value.split('\n').length);$('line-numbers').textContent=Array.from({length:n},(_,i)=>i+1).join('\n');}
function selectLesson(index){
  if(index<0||index>=LESSONS.length)return;
  sketches[model.lesson]=$('code').value||SKETCHES[model.lesson];silenceAudio();
  current=index;const l=LESSONS[index];model.reset(l.id);xray=false;topView=false;scene?.setXray(false);scene?.setLesson(l.id);
  $('lesson-context').textContent=`${String(index+1).padStart(2,'0')} / 06 · ${l.tag}`;$('lesson-title').textContent=l.title;$('lesson-subtitle').textContent=l.subtitle;
  $('panel-tag').textContent=l.tag;$('lesson-description').textContent=l.description;$('lesson-steps').innerHTML=l.steps.map(s=>`<li>${s}</li>`).join('');
  $('code').value=sketches[l.id];lines();$('scope-label').textContent=l.signal+' · simulated';$('scope-unit').textContent=l.unit;$('pin-label').textContent=l.pin;
  $('component-control').hidden=l.id!=='board';$('component-tip').hidden=true;
  $('steps-details').open=false;
  $('previous').disabled=index===0;$('next').textContent=index===5?'Back to the board ↺':'Next experiment →';
  $('scope-info').textContent=l.id==='chirp'?'Analytic waveform':'60 samples / s';
  $('scene-caption').textContent=l.id==='plant'?'Sensor → controller → driver → pump':l.id==='board'?'Pipit One · procedural 3D model':l.tag+' · interactive model';
  const notes={board:'A 3.3 V logic system. Select a part to explore.',pwm:'Vavg = 3.3 × duty / 100. Brightness is time-averaged.',dial:'12-bit ADC: code = round(Vin / 3.3 × 4095).',distance:'d = 343 m/s × echo time / 2. Ideal air model.',chirp:'Tone shown at a millisecond time scale to avoid aliasing.',plant:'Pump supply is separate. GPIO controls a transistor driver.'};
  $('principle').textContent=notes[l.id];$('console').textContent=l.id==='board'?'Ready. Select a component to explore.':'Ready. Press Run sketch to start.';$('console').className='';
  renderInputs();renderNav();updateViewButtons();updateUI();drawScope();
}
function runSketch(){
  try{model.run($('code').value);sketches[model.lesson]=$('code').value;markComplete();$('console').className='';$('console').textContent='Running · '+(model.lesson==='plant'?`pump ON below ${model.settings.threshold}%, OFF at ${model.settings.stop}%.`:'parameters applied to the simulated circuit.');updateUI();updateAudio();return true;}
  catch(e){model.running=false;silenceAudio();$('console').textContent=e.message;$('console').title=e.message;$('console').className='error';$('run-status').textContent='Sketch error';$('run-status').className='status error';$('run').textContent='▶ Run sketch';$('run').className='run-button';return false;}
}
function stopSketch(){model.running=false;silenceAudio();$('console').textContent='Stopped · signal history preserved.';updateUI();}
function updateViewButtons(){for(const [id,on] of [['view-3d',!topView],['view-top',topView],['xray',xray]]){$(id).classList.toggle('selected',on);$(id).setAttribute('aria-pressed',String(on));}}
function inspectPart(id){const p=PARTS[id];if(!p)return;$('component-tip').hidden=false;$('component-tip').querySelector('strong').textContent=p.name;$('component-tip').querySelector('span').textContent=p.description;scene?.highlight(id);if(model.lesson==='board'){markComplete();if(['mcu','radio','usb','ports','led'].includes(id))$('component-select').value=id;}}

function updateUI(){
  const l=LESSONS[current],s=model.settings,r=model.read();
  const hasError=$('console').classList.contains('error');$('run-status').textContent=hasError?'Sketch error':model.running?'Running':'Ready';$('run-status').className='status'+(hasError?' error':model.running?' running':'');$('run').textContent=model.running?'■ Stop':'▶ Run sketch';$('run').className='run-button'+(model.running?' stopped':'');
  for(const key of ['duty','frequency','dial','distance','tone','moisture']){const input=$('input-'+key),out=$('output-'+key);if(input&&document.activeElement!==input)input.value=s[key];if(out){const unit={duty:'%',frequency:'Hz',dial:'%',distance:'cm',tone:'Hz',moisture:'%'}[key];out.textContent=`${key==='moisture'?s[key].toFixed(1):Number(s[key].toFixed(2))} ${unit}`;}}
  const row=(k,v)=>`<div class="readout-row"><span>${k}</span><strong>${v}</strong></div>`;
  const data={board:[['Logic supply','3.30 V'],['ADC resolution','12 bit'],['GPIO logic','0 / 3.3 V']],pwm:[['Duty cycle',s.duty.toFixed(0)+'%'],['Average voltage',r.voltage.toFixed(2)+' V'],['Period',(1000/s.frequency).toFixed(0)+' ms']],dial:[['Input voltage',r.voltage.toFixed(2)+' V'],['ADC code',r.adc+' / 4095'],['LED level',s.dial.toFixed(0)+'%']],distance:[['Distance',s.distance.toFixed(1)+' cm'],['Echo time',r.echoUs.toFixed(0)+' µs'],['Near (<25 cm)',s.distance<25?'Yes':'No']],chirp:[['Tone',s.tone.toFixed(0)+' Hz'],['Period',(1000/s.tone).toFixed(2)+' ms'],['Audio',audio?.enabled&&model.running?'Enabled':'Muted']],plant:[['Soil moisture',s.moisture.toFixed(1)+'%'],['Pump',r.pump?'ON · watering':'OFF'],['Start / stop',`${s.threshold}% / ${s.stop}%`]]}[l.id];
  $('readout').innerHTML=data.map(([k,v])=>row(k,v)).join('');
  const value=l.id==='pwm'?(model.running?r.value:0):l.id==='chirp'?(model.running?s.tone:0):r.value;
  $('scope-value').textContent=['board','pwm','dial'].includes(l.id)?value.toFixed(2):value.toFixed(l.id==='distance'||l.id==='plant'?1:0);$('scope-unit').textContent=l.id==='chirp'?'Hz':l.unit;
  $('scope-empty').hidden=model.history.length>0;
  if(model.running){$('scope-time').textContent=l.id==='chirp'?`Time · 0–${(4000/s.tone).toFixed(2)} ms`:`Time · ${Math.max(0,model.time-5).toFixed(1)}–${Math.max(5,model.time).toFixed(1)} s`;}
}

function drawScope(){
  const canvas=$('scope'),rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;
  const dpr=Math.min(devicePixelRatio,2);const w=Math.round(rect.width*dpr),h=Math.round(rect.height*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}
  const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const width=rect.width,height=rect.height;ctx.clearRect(0,0,width,height);
  const left=33,right=10,top=12,bottom=22,pw=width-left-right,ph=height-top-bottom,l=LESSONS[current];const max=l.max;
  ctx.font='10px Plex, sans-serif';ctx.strokeStyle='#315044';ctx.lineWidth=.6;ctx.fillStyle='#c1d2c8';
  for(let i=0;i<=4;i++){const y=top+ph*i/4;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(width-right,y);ctx.stroke();ctx.textAlign='right';ctx.fillText((max*(1-i/4)).toFixed(max<10?1:0),left-7,y+3);}
  for(let i=0;i<=5;i++){const x=left+pw*i/5;ctx.beginPath();ctx.moveTo(x,top);ctx.lineTo(x,height-bottom);ctx.stroke();}
  const span=l.id==='chirp'?4/model.settings.tone:5;const end=l.id==='chirp'?span:Math.max(5,model.time),start=end-span;
  ctx.textAlign='left';ctx.fillText(l.id==='chirp'?'0':start.toFixed(1),left,height-6);ctx.textAlign='center';ctx.fillText(l.id==='chirp'?(span*500).toFixed(1):((start+end)/2).toFixed(1),left+pw/2,height-6);ctx.textAlign='right';ctx.fillText(l.id==='chirp'?(span*1000).toFixed(1)+' ms':end.toFixed(1)+' s',width-right,height-6);
  if(!model.history.length)return;
  ctx.save();ctx.beginPath();ctx.rect(left,top-1,pw,ph+2);ctx.clip();ctx.strokeStyle='#a7d6bd';ctx.lineWidth=1.5;ctx.beginPath();let begun=false;
  if(l.id==='chirp'){
    // An analytic four-period window. Sampling a 440 Hz signal at 60 Hz would alias.
    for(let i=0;i<=pw*2;i++){const x=left+i/2;const value=(i/(pw*2)*4)%1<.5?3.3:0;const y=top+ph*(1-value/max);if(!begun){ctx.moveTo(x,y);begun=true;}else ctx.lineTo(x,y);}
  }else for(const p of model.history){if(p.t<start)continue;const x=left+(p.t-start)/span*pw,y=top+ph*(1-p.v/max);if(!begun){ctx.moveTo(x,y);begun=true;}else ctx.lineTo(x,y);}
  ctx.stroke();ctx.restore();
}

async function toggleAudio(){
  if(!audio){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){$('console').textContent='Audio is unavailable in this browser.';return;}const context=new AC(),gain=context.createGain(),osc=context.createOscillator();gain.gain.value=0;osc.type='sine';osc.connect(gain);gain.connect(context.destination);osc.start();audio={context,gain,osc,enabled:false};}
  await audio.context.resume();audio.enabled=!audio.enabled;const b=$('audio');if(b){b.textContent=audio.enabled?'Mute sound ♫':'Enable sound ♫';b.setAttribute('aria-pressed',String(audio.enabled));b.classList.toggle('sound-on',audio.enabled);}updateAudio();updateUI();
}
function updateAudio(){if(!audio)return;audio.osc.frequency.setTargetAtTime(model.settings.tone,audio.context.currentTime,.025);audio.gain.gain.setTargetAtTime(audio.enabled&&model.running&&model.lesson==='chirp'?.025:0,audio.context.currentTime,.04);}
function silenceAudio(){if(audio){audio.enabled=false;audio.gain.gain.setTargetAtTime(0,audio.context.currentTime,.02);}}

const bounds=[0,6,12,18,25,30,42.5];
function applyTour(seconds){
  const t=Math.max(0,Math.min(42.499,seconds));let idx=0;while(idx<5&&t>=bounds[idx+1])idx++;if(idx!==current)selectLesson(idx);
  if(!model.running)runSketch();const local=t-bounds[idx];
  if(idx===0){const inside=local>3;if(inside!==xray){xray=inside;scene?.setXray(xray);updateViewButtons();}}
  if(idx===1){model.settings.duty=Math.round(10+80*(local/6));$('code').value=$('code').value.replace(/(duty\s*:\s*)\d+(?:\.\d+)?/,`$1${model.settings.duty}`);}
  if(idx===2)model.settings.dial=50+45*Math.sin(local*.9);
  if(idx===3)model.settings.distance=50+37*Math.sin(local*.75);
  if(idx===4){model.settings.tone=Math.round(220+local*140);$('code').value=$('code').value.replace(/(frequency\s*:\s*)\d+(?:\.\d+)?/,`$1${model.settings.tone}`);}
  if(idx===5&&local<.1){model.settings.moisture=22;model.pump=true;}
  $('tour-progress').querySelector('span').style.width=`${t/42.5*100}%`;
}
function startTour(){if(tour)return;sketches[model.lesson]=$('code').value;savedTourSketches={...sketches};selectLesson(0);Object.assign(sketches,SKETCHES);$('code').value=SKETCHES.board;tourElapsed=0;tour=true;$('tour').textContent='■ Stop reference tour';$('tour-progress').hidden=false;applyTour(0);}
function stopTour(){if(!tour)return;tour=null;$('tour').textContent='▷ Play reference tour';$('tour-progress').hidden=true;if(savedTourSketches){Object.assign(sketches,savedTourSketches);$('code').value=sketches[model.lesson];savedTourSketches=null;lines();}}

function exportCSV(){
  if(!model.history.length){$('console').textContent='Run the sketch before exporting a signal.';return;}
  const l=LESSONS[current];let rows=model.history;if(l.id==='chirp')rows=Array.from({length:801},(_,i)=>({t:i/800*4/model.settings.tone,v:(i/800*4)%1<.5?3.3:0}));
  const header=`# Simulated teaching model; lesson=${l.id}; ${l.id==='chirp'?'analytic four-period waveform':'fixed-step model; 60 Hz history'}\ntime_s,signal_${l.unit}\n`;
  const blob=new Blob([header+rows.map(p=>`${p.t.toFixed(7)},${p.v.toFixed(5)}`).join('\n')],{type:'text/csv'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pipit-${l.id}-simulated.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}

$('code').addEventListener('input',lines);$('code').addEventListener('scroll',()=>{$('line-numbers').scrollTop=$('code').scrollTop;});
$('run').addEventListener('click',()=>{stopTour();if(model.running)stopSketch();else runSketch();});
$('restore').addEventListener('click',()=>{stopTour();$('code').value=SKETCHES[model.lesson];lines();$('console').textContent='Example restored. Run to apply its parameters.';$('console').className='';});
$('previous').addEventListener('click',()=>{stopTour();selectLesson(current-1);});$('next').addEventListener('click',()=>{stopTour();selectLesson((current+1)%6);});
$('mobile-lessons').addEventListener('change',e=>{stopTour();selectLesson(Number(e.target.value));});
$('component-select').addEventListener('change',e=>inspectPart(e.target.value));
$('view-3d').addEventListener('click',()=>{topView=false;scene?.resetCamera();updateViewButtons();});$('view-top').addEventListener('click',()=>{topView=true;scene?.resetCamera(true);updateViewButtons();});
$('xray').addEventListener('click',()=>{xray=!xray;scene?.setXray(xray);updateViewButtons();if(xray){$('scene-caption').textContent='Conceptual chip view · signal flow, not a die layout';inspectPart('mcu');}});
$('reset-camera').addEventListener('click',()=>{topView=false;scene?.resetCamera();updateViewButtons();});$('tour').addEventListener('click',()=>{if(tour)stopTour();else startTour();});
$('reset-all').addEventListener('click',()=>{completed.clear();try{localStorage.removeItem('pipit-completed');}catch{}renderNav();});$('export').addEventListener('click',exportCSV);
